python3 -c "
import json
import re

# Load each bulletin and extract the FFO-1 table data
files = [
    ('/app/resources/treasury_bulletin_1996_09.json', '1996'),
    ('/app/resources/treasury_bulletin_2001_09.json', '2001'),
    ('/app/resources/treasury_bulletin_2006_09.json', '2006'),
    ('/app/resources/treasury_bulletin_2011_09.json', '2011')
]

all_data = {}

for f, year in files:
    with open(f, 'r') as fp:
        data = json.load(fp)

    doc = data.get('document', {})
    elements = doc.get('elements', [])

    # Find the FFO-1 table 
    for i, elem in enumerate(elements):
        if isinstance(elem, dict):
            content = elem.get('content', '') or ''
            if 'On-budget receipts' in content and 'Off-budget receipts' in content:
                # Extract all fiscal year rows 
                rows = re.findall(r'<tr><td>(\\d{4})</td><td>([0-9,]+)</td><td>([0-9,]+)</td><td>([0-9,]+)</td>', content)
                for row in rows:
                    fy = int(row[0])
                    on_budget = int(row[2].replace(',', ''))
                    off_budget = int(row[3].replace(',', ''))
                    if fy not in all_data:
                        all_data[fy] = {}
                    all_data[fy][year] = (on_budget, off_budget)
                break

# Print what we have for years 1991-2010
for fy in range(1991, 2011):
    if fy in all_data:
        print(f'FY{fy}: {all_data[fy]}')
    else:
        print(f'FY{fy}: MISSING')
"
